// Runs whenever a LendLoop workflow fails after its retries, so nothing fails silently.
// Always logs; also posts to a chat webhook (Slack/Discord) when ALERT_WEBHOOK_URL is set.
const { workflow, execution } = $input.first().json;
const alert = {
  workflow: workflow?.name,
  executionId: execution?.id,
  failedNode: execution?.lastNodeExecuted,
  error: execution?.error?.message,
  url: execution?.url,
};
console.error('[LendLoop automation failed]', JSON.stringify(alert));
const hook = $env.ALERT_WEBHOOK_URL;
if (hook) {
  const text = `LendLoop automation failed: ${alert.workflow} at "${alert.failedNode}": ${alert.error}\n${alert.url ?? ''}`;
  await this.helpers.httpRequest({ method: 'POST', url: hook, json: true, body: { content: text, text } });
}
return [{ json: alert }];
